// Extract threads from webhook body
const webhookData = $input.first().json;
const threads = webhookData.body || [];

return threads.map(thread => {
  const text = (thread.threadText || '').trim()
    .replace(/<@[A-Z0-9]+>/g, '')
    .replace(/<#[A-Z0-9]+\|[^>]+>/g, '')
    .replace(/<(https?:\/\/[^|>]+)\|[^>]+>/g, '$1')
    .replace(/<(https?:\/\/[^>]+)>/g, '$1')
    .replace(/\s{3,}/g, '\n\n')
    .trim();

  return {
    json: {
      threadText: text,
      messageCount: thread.messageCount || 0,
      channel: thread.channel || '#unknown'
    }
  };
});

