// Parse batch AI output and split into individual items

const input = $input.first().json;
let summaries = [];

// Extract output from AI Agent response
const rawOutput = input.output || input.text || input.response || input;

// ---------- Helper: Safe JSON Parse ----------
function safeParse(data) {
  if (typeof data === 'string') {
    const cleaned = data
      .replace(/^```json\s*/i, '')
      .replace(/```\s*$/i, '')
      .trim();
    return JSON.parse(cleaned);
  }
  return data;
}

// ---------- Helper: Extract tickets array ----------
function extractTickets(parsed) {
  if (!parsed) return null;

  if (Array.isArray(parsed)) return parsed;

  if (parsed.tickets && Array.isArray(parsed.tickets)) {
    return parsed.tickets;
  }

  if (parsed.output && parsed.output.tickets && Array.isArray(parsed.output.tickets)) {
    return parsed.output.tickets;
  }

  if (parsed.summaries && Array.isArray(parsed.summaries)) {
    return parsed.summaries;
  }

  return null;
}

try {
  const parsed = safeParse(rawOutput);
  const extracted = extractTickets(parsed);

  if (!extracted) {
    throw new Error('No valid tickets array found in response');
  }

  summaries = extracted.map((s, idx) => {
    // ---------- SUMMARY PROCESSING ----------
    const summary =
      typeof s.summary === 'string' && s.summary.trim().length > 0
        ? s.summary.trim()
        : (typeof s.tldr === 'string' ? s.tldr.trim() : 'No summary generated');

    // Optional: enforce max length (clean for UI)
    const normalizedSummary = summary.length > 300
      ? summary.substring(0, 297) + '...'
      : summary;

    return {
      index: typeof s.index === 'number' ? s.index : idx,

      // ✅ KEEP ORIGINAL SUMMARY
      summary: normalizedSummary,

      // ✅ TLDR (can be same or shorter version)
      tldr: normalizedSummary,

      participants: Array.isArray(s.participants) ? s.participants : [],

      keyPoints: Array.isArray(s.keyPoints)
        ? s.keyPoints
        : (s.actionItems || []).slice(0, 3),

      actionItems: Array.isArray(s.actionItems) ? s.actionItems : [],

      urgency: ['HIGH', 'MEDIUM', 'LOW', 'CRITICAL'].includes(s.urgency)
        ? s.urgency
        : 'MEDIUM',

      status: ['Resolved', 'In Progress', 'Blocked', 'Needs Decision'].includes(s.status)
        ? s.status
        : 'In Progress',

      channel: s.channel || input.channel || '#unknown',

      category: s.category || 'OTHER',

      batchProcessedAt: new Date().toISOString()
    };
  });

} catch (error) {
  return [
    {
      json: {
        error: true,
        errorMessage: error.message,
        rawOutput:
          typeof rawOutput === 'string'
            ? rawOutput.substring(0, 1000)
            : JSON.stringify(rawOutput).substring(0, 1000),
        timestamp: new Date().toISOString()
      }
    }
  ];
}

return summaries.map(summary => ({
  json: summary
}));

